//! Master key, API keys and webhook secrets.
//!
//! # Master key
//!
//! The 32-byte server master key is generated by the installer and loaded from
//! a root-owned file. It wraps per-message content keys through
//! [`MasterKey::wrap_content_key`] / [`MasterKey::unwrap_content_key`], which
//! delegate to the domain-separated AEAD envelope in [`crate::seal`]. The key
//! bytes live in `Zeroizing` storage and are wiped on drop; `Debug` is redacted.
//!
//! # API keys
//!
//! Keys are `pk_` + 32 random bytes in unpadded base64url (43 chars) and are
//! stored only as an Argon2id PHC hash. [`verify_api_key`] performs the full
//! Argon2id verification — **expensive by design** (~19 MiB of memory and tens
//! of milliseconds of CPU per attempt). The API layer MUST therefore rate-limit
//! verification attempts and cache verified key ids (so a session checks the
//! hash once instead of per request); see `SECURITY.md` for the operational
//! guidance. Without those two controls the KDF itself becomes the
//! denial-of-service surface.

use argon2::password_hash::{
    rand_core::OsRng, PasswordHash, PasswordHasher, PasswordVerifier, SaltString,
};
use argon2::Argon2;
use chacha20poly1305::{KeyInit, XChaCha20Poly1305};
use rand_core::RngCore;
use zeroize::Zeroizing;

use crate::error::{CryptoError, Result};

/// Fixed, valid Argon2id PHC string used only to burn the same KDF work when
/// the *stored* hash cannot be parsed. It never matches any input.
pub(crate) const DUMMY_PHC: &str = concat!(
    "$argon2id$v=19$m=19456,t=2,p=1$",
    "cGlnZW9uLWR1bW15LXNsdA",
    "$AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
);

/// The server master key: 32 bytes, generated by the installer, loaded from a
/// root-owned file. Held in `Zeroizing` so the buffer is wiped on drop.
#[derive(Clone)]
pub struct MasterKey(Zeroizing<[u8; 32]>);

impl MasterKey {
    /// Generate a fresh random master key (installer path).
    pub fn generate() -> Self {
        let mut k = Zeroizing::new([0u8; 32]);
        OsRng.fill_bytes(k.as_mut());
        MasterKey(k)
    }

    /// Parse from raw 32 bytes or 64 hex characters (either case).
    ///
    /// A 32-character *hex string* is rejected with
    /// [`CryptoError::AmbiguousKeyMaterial`]: operators who paste 32 hex chars
    /// mean a 256-bit key and actually supplied 128 bits. Provide 64 hex chars
    /// or 32 raw bytes instead.
    pub fn parse(material: &[u8]) -> Result<Self> {
        match material.len() {
            32 => {
                if material.iter().all(u8::is_ascii_hexdigit) {
                    return Err(CryptoError::AmbiguousKeyMaterial);
                }
                let mut k = Zeroizing::new([0u8; 32]);
                k.copy_from_slice(material);
                Ok(MasterKey(k))
            }
            64 => {
                let decoded =
                    Zeroizing::new(hex::decode(material).map_err(|_| CryptoError::BadHex)?);
                if decoded.len() != 32 {
                    return Err(CryptoError::BadHex);
                }
                let mut k = Zeroizing::new([0u8; 32]);
                k.copy_from_slice(&decoded);
                Ok(MasterKey(k))
            }
            other => Err(CryptoError::BadKeyFile(other)),
        }
    }

    /// Load from a key file (raw or hex). Leading/trailing ASCII whitespace is
    /// trimmed first, so `echo $(cat key.hex)` style files with a trailing
    /// newline work. A raw binary key whose first or last byte happens to be
    /// ASCII whitespace is rejected (fail-safe) rather than silently mangled.
    ///
    /// Caller is responsible for file permissions; startup checks them outside
    /// this crate.
    pub fn from_file(path: &std::path::Path) -> Result<Self> {
        // Read straight into wipe-on-drop storage: the file is key material.
        let material = Zeroizing::new(std::fs::read(path)?);
        Self::parse(material.trim_ascii())
    }

    /// Wrap a 32-byte content key under this master key, bound to `aad`.
    /// Returns a domain-separated, versioned envelope (see [`crate::seal`]).
    pub fn wrap_content_key(&self, key: &[u8; 32], aad: &[u8]) -> Result<Vec<u8>> {
        crate::seal::wrap_key(self.bytes(), key, aad)
    }

    /// Unwrap a blob produced by [`MasterKey::wrap_content_key`]. The `aad`
    /// must match the one used to wrap, otherwise authentication fails.
    pub fn unwrap_content_key(&self, blob: &[u8], aad: &[u8]) -> Result<[u8; 32]> {
        crate::seal::unwrap_key(self.bytes(), blob, aad)
    }

    /// Access for authenticated encryption only.
    pub(crate) fn bytes(&self) -> &[u8; 32] {
        &self.0
    }
}

impl std::fmt::Debug for MasterKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // Never leak key material through Debug.
        f.write_str("MasterKey([REDACTED])")
    }
}

/// Derive an AEAD instance from a 32-byte key (XChaCha20-Poly1305: 24-byte nonces,
/// no nonce-collision risk even at millions of messages).
pub(crate) fn aead(key: &[u8; 32]) -> XChaCha20Poly1305 {
    XChaCha20Poly1305::new(key.into())
}

/// Generate a new API key: `pk_` + 32 random bytes, base64url unpadded.
pub fn generate_api_key() -> String {
    format!("pk_{}", b64url(&random_bytes(32)))
}

/// Parse an API key produced by [`generate_api_key`] back into its 32 raw bytes.
///
/// Enforces the exact wire format: `pk_` prefix, then 43 unpadded base64url
/// characters decoding to 32 bytes (canonical encoding, no padding, no
/// whitespace).
pub fn parse_api_key(key: &str) -> Result<[u8; 32]> {
    const PREFIX: &str = "pk_";
    const BODY_LEN: usize = 43;

    let body = key
        .strip_prefix(PREFIX)
        .ok_or_else(|| CryptoError::ApiKeyFormat(format!("missing `{PREFIX}` prefix")))?;
    if body.len() != BODY_LEN {
        return Err(CryptoError::ApiKeyFormat(format!(
            "expected {BODY_LEN} base64url characters after `{PREFIX}`, got {}",
            body.len()
        )));
    }
    let decoded = zeroize::Zeroizing::new(
        b64url_decode(body)
            .ok_or_else(|| CryptoError::ApiKeyFormat("invalid base64url characters".into()))?,
    );
    if decoded.len() != 32 {
        return Err(CryptoError::ApiKeyFormat(format!(
            "decoded to {} bytes, expected 32",
            decoded.len()
        )));
    }
    // Reject non-canonical encodings (spare trailing bits set) so one key has
    // exactly one textual form.
    if b64url(&decoded) != body {
        return Err(CryptoError::ApiKeyFormat(
            "non-canonical base64url encoding".into(),
        ));
    }
    let mut out = [0u8; 32];
    out.copy_from_slice(&decoded);
    Ok(out)
}

/// Generate a webhook signing secret: `whsec_` + 32 random bytes, base64url unpadded.
pub fn generate_webhook_secret() -> String {
    format!("whsec_{}", b64url(&random_bytes(32)))
}

/// Hash an API key for storage (Argon2id v19, PHC string format).
pub fn hash_api_key(api_key: &str) -> Result<String> {
    let salt = SaltString::generate(&mut OsRng);
    Argon2::default()
        .hash_password(api_key.as_bytes(), &salt)
        .map(|h| h.to_string())
        .map_err(|e| CryptoError::Hashing(e.to_string()))
}

/// Verify an API key against its stored PHC hash.
///
/// The amount of Argon2id work performed is comparable whether or not the stored
/// hash parses: a malformed hash is checked against a fixed dummy PHC string
/// before returning `false`, so the parse outcome is not observable in timing.
/// Argon2id is deliberately expensive — callers must rate-limit and cache
/// verified key ids (see module docs).
pub fn verify_api_key(api_key: &str, phc_hash: &str) -> bool {
    match PasswordHash::new(phc_hash) {
        Ok(parsed) => Argon2::default()
            .verify_password(api_key.as_bytes(), &parsed)
            .is_ok(),
        Err(_) => {
            // Burn equivalent KDF work on a fixed dummy hash; result is ignored
            // and the outcome is always `false`.
            if let Ok(dummy) = PasswordHash::new(DUMMY_PHC) {
                let _ = Argon2::default().verify_password(api_key.as_bytes(), &dummy);
            }
            false
        }
    }
}

pub(crate) fn random_bytes(n: usize) -> zeroize::Zeroizing<Vec<u8>> {
    let mut buf = vec![0u8; n];
    OsRng.fill_bytes(&mut buf);
    zeroize::Zeroizing::new(buf)
}

pub(crate) fn b64url(data: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    // Minimal base64url (unpadded) — avoids pulling a full base64 crate.
    let mut out = String::with_capacity(data.len().div_ceil(3) * 4);
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = *chunk.get(1).unwrap_or(&0) as u32;
        let b2 = *chunk.get(2).unwrap_or(&0) as u32;
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(CHARS[(n >> 18) as usize & 63] as char);
        out.push(CHARS[(n >> 12) as usize & 63] as char);
        if chunk.len() > 1 {
            out.push(CHARS[(n >> 6) as usize & 63] as char);
        }
        if chunk.len() > 2 {
            out.push(CHARS[n as usize & 63] as char);
        }
    }
    out
}

/// Inverse of [`b64url`]: unpadded base64url. Returns `None` on characters
/// outside the alphabet or an impossible length.
pub(crate) fn b64url_decode(input: &str) -> Option<Vec<u8>> {
    fn val(b: u8) -> Option<u32> {
        Some(match b {
            b'A'..=b'Z' => (b - b'A') as u32,
            b'a'..=b'z' => (b - b'a') as u32 + 26,
            b'0'..=b'9' => (b - b'0') as u32 + 52,
            b'-' => 62,
            b'_' => 63,
            _ => return None,
        })
    }

    let bytes = input.as_bytes();
    if bytes.len() % 4 == 1 {
        return None; // no encoding produces a single trailing character
    }
    let mut out = Vec::with_capacity(bytes.len() / 4 * 3 + 3);
    for chunk in bytes.chunks(4) {
        let mut acc = 0u32;
        for (i, b) in chunk.iter().enumerate() {
            acc |= val(*b)? << (18 - 6 * i);
        }
        // 1 char → 0 bytes, 2 → 1, 3 → 2, 4 → 3.
        for i in 0..chunk.len() - 1 {
            out.push((acc >> (16 - 8 * i)) as u8);
        }
    }
    Some(out)
}
